package ru.kupiora.radar;
import android.content.Context;import org.json.*;
final class Inbox {
 static final String KEY="notification_inbox";
 static JSONArray load(Context c){try{return new JSONArray(Store.prefs(c).getString(KEY,"[]"));}catch(Exception e){return new JSONArray();}}
 static int unread(JSONArray entries){int count=0;for(int i=0;i<entries.length();i++){JSONObject entry=entries.optJSONObject(i);if(entry!=null&&!entry.optBoolean("read"))count++;}return count;}
 static int count(Context c){return unread(load(c));}
 static JSONArray append(JSONArray old,JSONObject item){JSONArray result=new JSONArray();for(int i=0;i<old.length();i++)if(item.optString("id").equals(old.optJSONObject(i)==null?"":old.optJSONObject(i).optString("id")))return old;result.put(item);for(int i=0;i<old.length()&&result.length()<200;i++)result.put(old.opt(i));return result;}
 static synchronized boolean add(Context c,String id,String title,String body,boolean test)throws Exception {JSONArray old=load(c);JSONObject item=new JSONObject().put("id",id).put("title",title).put("body",body).put("test",test).put("read",false).put("createdAt",System.currentTimeMillis());JSONArray next=append(old,item);if(next==old)return false;if(!Store.prefs(c).edit().putString(KEY,next.toString()).commit())throw new IllegalStateException("Уведомление не удалось сохранить");return true;}
 static boolean matchesCategory(JSONObject entry,String category){return category==null||category.isEmpty()||category.equals(entry.optString("categoryId"));}
 static int unreadFor(JSONArray entries,String category){int n=0;for(int i=0;i<entries.length();i++){JSONObject x=entries.optJSONObject(i);if(x!=null&&!x.optBoolean("read")&&matchesCategory(x,category))n++;}return n;}
 static int unreadFor(Context c,String category){return unreadFor(load(c),category);}
 static JSONObject documentNotice(JSONObject document,long now)throws Exception{return new JSONObject().put("id","legal:"+document.getString("id")).put("title",document.getString("title")).put("body",document.getString("summary")).put("categoryId",document.getString("categoryId")).put("sourceUrl",document.getString("sourceUrl")).put("publishedAt",document.optString("publishedAt")).put("effectiveAt",document.optString("effectiveAt")).put("createdAt",now).put("read",false).put("test",false);}
 static synchronized boolean addDocument(Context c,JSONObject document)throws Exception{JSONArray old=load(c),next=append(old,documentNotice(document,System.currentTimeMillis()));if(old==next)return false;if(!Store.prefs(c).edit().putString(KEY,next.toString()).commit())throw new IllegalStateException("Не удалось сохранить изменение");return true;}
 static synchronized void markCategoryRead(Context c,String category){try{JSONArray entries=load(c);for(int i=0;i<entries.length();i++){JSONObject x=entries.optJSONObject(i);if(x!=null&&matchesCategory(x,category))x.put("read",true);}if(Store.prefs(c).edit().putString(KEY,entries.toString()).commit())SyncJob.updateSystemBadge(c);}catch(Exception ignored){}}
 static synchronized void importLegacy(Context c){if(Store.prefs(c).getBoolean("notification_center_initialized",false))return;try{for(android.service.notification.StatusBarNotification status:c.getSystemService(android.app.NotificationManager.class).getActiveNotifications()){android.os.Bundle extras=status.getNotification().extras;String title=String.valueOf(extras.getCharSequence(android.app.Notification.EXTRA_TITLE,"Уведомление")),body=String.valueOf(extras.getCharSequence(android.app.Notification.EXTRA_TEXT,""));add(c,"legacy:"+status.getKey()+":"+status.getPostTime(),title,body,title.startsWith("Тест"));}Store.prefs(c).edit().putBoolean("notification_center_initialized",true).commit();}catch(Exception ignored){}}
 static JSONArray read(JSONArray entries,String id)throws Exception{return setRead(entries,id,true);}
 static JSONArray setRead(JSONArray entries,String id,boolean read)throws Exception{JSONArray result=new JSONArray(entries.toString());for(int i=0;i<result.length();i++){JSONObject x=result.getJSONObject(i);if(id==null||id.equals(x.optString("id")))x.put("read",read);}return result;}
 static synchronized void markRead(Context c,String id){mark(c,id,true);}
 static synchronized void mark(Context c,String id,boolean read){try{Store.prefs(c).edit().putString(KEY,setRead(load(c),id,read).toString()).commit();SyncJob.updateSystemBadge(c);}catch(Exception ignored){}}
}
